private void xrLabel29_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
    if (GetCurrentColumnValue("LLOJDOKUMENTIMAGAZINE") != null)
            {
                string llojDok = GetCurrentColumnValue("LLOJDOKUMENTIMAGAZINE").ToString();
                string nrDok = GetCurrentColumnValue("NRDOK").ToString();
                string idDok = GetCurrentColumnValue("IDKOKAMAGAZINA").ToString();
                string url = AlphaWebReports.raporteUtil.ktheUrlDokumentiRaportKlientFurnitor(llojDok, idDok, nrDok, scopeID );
                if (url != "")
                {
                    xrLabel29.NavigateUrl = url;
                    xrLabel29.ForeColor = Color.SteelBlue;
                    xrLabel29.Target="_self";
                }
		else  {
                    xrLabel29.NavigateUrl = "";
                    xrLabel29.ForeColor = Color.Black;
                }

            }
}

